-- Workstream E: team board seed (claim maps, chat, Case 10 gap, Case 9 v7)
-- Idempotent. Reserved migration number 00015.
-- Generated by scripts/emit-team-seed-sql.ts — re-run to refresh.

-- Case 10 Team 3: leave Lead 1 empty so the board shows a gap
delete from case_roles where team_id = '33333333-3333-3333-3333-333333333333' and case_id = (select id from cases where number = 10) and role = 'lead_1';

-- Case 9: Katie made Jainam Lead 1; Daniel takes counter
delete from case_roles where team_id = '33333333-3333-3333-3333-333333333333' and case_id = (select id from cases where number = 9) and (role in ('lead_1', 'counter_arguer') or person_id = 'a3333333-3333-3333-3333-333333333304');
on conflict (id) do nothing;

-- Channels
on conflict (channel) do nothing;

-- Claim map versions
on conflict (team_id, case_id, version) do nothing;

-- Confirmations
on conflict (version_id, person_id) do nothing;

-- Alignment questions (Jainam on Case 9 v7)
on conflict (id) do nothing;

