  ('9face1b9-b175-4d85-9cbb-32823dcf6c87', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 'a3333333-3333-3333-3333-333333333304', 'lead_1', '2026-11-18T18:00:00.000Z', 'a3333333-3333-3333-3333-333333333303'),
