  ('e5632aec-de55-41da-a55e-c41315e48139', 'team:22222222-2222-2222-2222-222222222222', '22222222-2222-2222-2222-222222222222', '2026-11-01T00:00:00.000Z')
insert into claim_map_versions (id, team_id, case_id, version, body, change_summary, created_by, created_at) values
  ('34061253-06bc-454e-9a8d-cff00b2d4bcb', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 1), 4, '{"claims":[{"key":"c1","text":"Even a more accurate AI would not remove the core objection: decisions to kill need meaningful human judgment and a responsible human.","logic_line":"Because autonomous killing creates a responsibility gap (S1), humans \"in the loop\" drift into rubber-stamping (S2), and greater distance makes war easier to start (S3), accuracy alone cannot justify removing human judgment.","supports":[{"key":"s1","text":"The responsibility gap. When a machine selects and engages a target, no one may be fully answerable: not the programmer, the commander, or the machine."},{"key":"s2","text":"Automation bias. People formally \"in the loop\" come to defer to the system''s recommendation."},{"key":"s3","text":"Distance lowers the threshold for war. Each step that removes risk from the side using force makes force easier to choose."}],"counterclaim_response":"(3) that''s why Claim 2 puts the limits in law. / (2) we accept decision support; the objection is to delegating the kill decision. / a system that ranks targets embeds choices about training data, thresholds and acceptable error. Excel doesn''t choose who lives."},{"key":"c2","text":"A company may refuse uses it judges unethical, but the binding limits on lethal autonomy and domestic mass surveillance belong in public law.","logic_line":"Because makers share responsibility for foreseeable uses of what they build (S1), democratic governments, not vendors, must set national policy (S2), and mass surveillance threatens the democratic accountability the military itself relies on (S3), the right answer is public, legal guardrails rather than private vetoes.","supports":[{"key":"s1","text":"Makers can be complicit in foreseeable uses. A company that knowingly supplies a tool for a use it believes is wrong shares responsibility for that use."},{"key":"s2","text":"Democratic legitimacy cuts the other way too. Unelected companies shouldn''t set military policy for a democracy, as the Pentagon argues in the case. That means the durable fix is law."},{"key":"s3","text":"Mass surveillance of citizens undermines democracy itself. People who know they are always watched speak and organize less freely."}],"counterclaim_response":"(3) that''s why Claim 2 puts the limits in law. / (2) we accept decision support; the objection is to delegating the kill decision. / a system that ranks targets embeds choices about training data, thresholds and acceptable error. Excel doesn''t choose who lives."}]}'::jsonb, 'Claim map at v4 from Team 3 prep.', 'a3333333-3333-3333-3333-333333333302', '2026-11-15T12:00:00.000Z'),
  ('5a62ee4b-b887-4cb7-91bc-9b1e6a00243a', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 3), 3, '{"claims":[{"key":"c1","text":"San Francisco was justified in keeping the memorial, and diplomatic pressure is not a valid reason to remove it.","logic_line":"Because San Francisco has a real connection to this history (S1), memorials serve justice for victims whose suffering hasn''t been adequately acknowledged (S2), and the statue honors victims rather than accusing today''s Japanese people (S3), keeping it was justified.","supports":[{"key":"s1","text":"Real connection. San Francisco has large Chinese and Korean communities, and the U.S. military reportedly took part in the abuse, so the U.S. shares some accountability."},{"key":"s2","text":"Memory is a form of justice owed to victims. When wrongs go unacknowledged, public memory is one of the few remedies left."},{"key":"s3","text":"Remembrance is not accusation. The statue honors \"all other women affected by such crimes,\" not only victims of Japan."}],"counterclaim_response":"(2) that''s why S3 of Claim 1 matters. / (3) honoring victims in your own city isn''t foreign policy. / apologies that survivors reject don''t close the question, and using diplomatic ties to pressure a city to remove a memorial treats memory as a bargaining chip."},{"key":"c2","text":"The right standard for public memory has four tests, and it binds the U.S. as much as Japan.","logic_line":"Because a principle we apply to others must apply to ourselves (S1), societies that confront their own wrongs show it can be done well (S2), and the community most connected to a history should decide, with victims at the center (S3), the U.S. must hold its own monuments to the same four tests.","supports":[{"key":"s1","text":"Consistency. Memorializing another country''s wrongs while honoring our own perpetrators is a double standard."},{"key":"s2","text":"Acknowledgment works. Countries can face their own atrocities without collapse."},{"key":"s3","text":"Local communities decide, with victims at the center"}],"counterclaim_response":"(2) that''s why S3 of Claim 1 matters. / (3) honoring victims in your own city isn''t foreign policy. / apologies that survivors reject don''t close the question, and using diplomatic ties to pressure a city to remove a memorial treats memory as a bargaining chip."}]}'::jsonb, 'Claim map at v3 from Team 3 prep.', 'a3333333-3333-3333-3333-333333333304', '2026-11-15T12:00:00.000Z'),
  ('ed3f2829-416b-4bad-85eb-1d1a4eeec1aa', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 4), 2, '{"claims":[{"key":"c1","text":"We have no moral duty to be beautiful.","logic_line":"Because duties attach to what we control and what we owe others (S1), treating beauty as a moral standard punishes people for traits they didn''t choose (S2), and a benefit to the individual is not an obligation (S3), there is no duty to be beautiful.","supports":[{"key":"s1","text":"Duties track control and what we owe others. \"Ought implies can\": morality can''t require what people can''t do, and much of appearance comes from genetics, illness or disability."},{"key":"s2","text":"Making beauty a moral ideal produces unjust judgments"},{"key":"s3","text":"Benefit is not duty. That something pays off doesn''t mean we owe it to anyone."}],"counterclaim_response":"See response. / See response. / the right response to unjust advantages is to reduce the bias in institutions, not to demand that everyone chase the ideal."},{"key":"c2","text":"Caring for one''s appearance is a permissible choice, but marketing extreme practices to young people and profiting from insecurity is wrong.","logic_line":"Because autonomous adults may shape their own bodies (S1), minors and insecure audiences can''t consent freely to a market built on their anxieties (S2), and each person''s maxxing raises the bar for everyone (S3), the practice is permissible as personal choice but its predatory promotion is not.","supports":[{"key":"s1","text":"Autonomy covers self-care. Grooming, fitness and even elective procedures can express a person''s own goals."},{"key":"s2","text":"Consent requires freedom from manipulation and enough maturity. The movement mainly targets adolescents."},{"key":"s3","text":"Looks work like an arms race. When everyone invests to look better than others, the standard rises and no one gains relative advantage, but everyone pays."}],"counterclaim_response":"See response. / See response. / the right response to unjust advantages is to reduce the bias in institutions, not to demand that everyone chase the ideal."}]}'::jsonb, 'Claim map at v2 from Team 3 prep.', 'a3333333-3333-3333-3333-333333333301', '2026-11-15T12:00:00.000Z'),
  ('e9e62c44-d331-4a8f-ae4d-7e1a9ac7f01c', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 5), 5, '{"claims":[{"key":"c1","text":"Markets on war, death and the removal of leaders are morally wrong.","logic_line":"Because these markets reward secret knowledge that insiders control (S1), they put a price on human lives and suffering (S2), and they can create incentives to cause or time the events themselves (S3), they should not exist.","supports":[{"key":"s1","text":"Inside knowledge decides these outcomes. When the event is a secret operation, the only people who can \"forecast\" well are the people planning it."},{"key":"s2","text":"Lives become commodities. Betting on a person''s death or a war treats the people affected as mere instruments for profit."},{"key":"s3","text":"Incentives can bend the event. When someone profits from an outcome they can influence, they have a reason to make it happen or time it."}],"counterclaim_response":"(3) the same accuracy is possible without money on death; forecasting tournaments like the Good Judgment Project do it without betting on lives (verify before citing). / in war markets, the information is often leaked secrets, which is the harm. / the same accuracy is possible without money on death; forecasting tournaments like the Good Judgment Project do it without betting on lives (verify before citing)."},{"key":"c2","text":"Markets on public, scheduled events can be permissible, with safeguards for fairness and gambling harm.","logic_line":"Because elections and economic data are public processes no single insider controls (S1), adults may risk their own money on their own judgment (S2), and strong safeguards can address insider trading and addiction (S3), these markets can be permissible.","supports":[{"key":"s1","text":"Public processes resist insiders. No one can secretly decide an election''s outcome the way a commander decides an operation."},{"key":"s2","text":"Autonomy. Adults may make risky choices with their own money."},{"key":"s3","text":"Safeguards work where gambling regulation already works"}],"counterclaim_response":"(3) the same accuracy is possible without money on death; forecasting tournaments like the Good Judgment Project do it without betting on lives (verify before citing). / in war markets, the information is often leaked secrets, which is the harm. / the same accuracy is possible without money on death; forecasting tournaments like the Good Judgment Project do it without betting on lives (verify before citing)."}]}'::jsonb, 'Claim map at v5 from Team 3 prep.', 'a3333333-3333-3333-3333-333333333302', '2026-11-15T12:00:00.000Z'),
  ('a6cb714e-482e-4295-af79-188ee1fdbe36', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 7), 6, '{"claims":[{"key":"c1","text":"Accessibility lawsuits, including serial ones, are justified civil-rights enforcement.","logic_line":"Because inaccessibility is a real wrong of exclusion (S1), the law deliberately recruited private enforcers (S2), and disability rights has always advanced through friction (S3), suing businesses that keep barriers is justified.","supports":[{"key":"s1","text":"The wrong is real. A ramp too steep to climb or a drive-through that sends deaf customers inside tells people the space is not for them."},{"key":"s2","text":"Private enforcement is the system''s design. Title III has no damages and the Justice Department can''t inspect every storefront; California added $4,000 precisely to recruit private enforcers."},{"key":"s3","text":"Activism as friction. Friction slows things down, but it also gives grip."}],"counterclaim_response":"See response. / (1) not discriminating by race costs nothing, you simply stop; removing a physical barrier takes capital, which is why the ADA limits the duty in existing buildings to what is readily achievable. / the Richmond suit produced a closed restaurant and no ramp, forever."},{"key":"c2","text":"The per-visit bounty pays for findings, not fixes, so enforcement should be redesigned around repair and scaled to knowledge, control and capacity.","logic_line":"Because a bounty rewards the violations cheapest to prove against the defendants least able to fight (S1), it can produce closures instead of ramps (S2), and responsibility for an inherited environment is shared and follows control (S3), the remedy should pay for repair and fall hardest on those with power.","supports":[{"key":"s1","text":"Selection effect. Litigation economics favors small defendants who settle and violations provable with a 12-inch level."},{"key":"s2","text":"Compliance by subtraction. The cheapest legal \"fix\" can be removing something rather than adding access."},{"key":"s3","text":"Responsibility follows control and capacity"}],"counterclaim_response":"See response. / (1) not discriminating by race costs nothing, you simply stop; removing a physical barrier takes capital, which is why the ADA limits the duty in existing buildings to what is readily achievable. / the Richmond suit produced a closed restaurant and no ramp, forever."}]}'::jsonb, 'Claim map at v6 from Team 3 prep.', 'a3333333-3333-3333-3333-333333333304', '2026-11-15T12:00:00.000Z'),
  ('d0704ffc-d573-4a3b-a602-21abefcc2d0b', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 6, '{"claims":[{"key":"c1","text":"The British Museum''s title is defective, and the duty to repair falls on the institution that still benefits.","logic_line":"Because the Stone changed hands as a spoil of war between empires (S1), keeping taken objects for being \"the better caretaker\" can''t be a universal rule (S2), and responsibility for an inherited wrong follows power and benefit (S3), the museum carries the duty to return it.","supports":[{"key":"s1","text":"A broken first link. A holding is just only if it was justly acquired and justly transferred."},{"key":"s2","text":"The caretaker maxim fails universalizability"},{"key":"s3","text":"Responsibility, not blame. Today''s trustees took nothing, but they hold the power and the benefit."}],"counterclaim_response":"See response. / returning one object out of 100,000+ displaces no one. / our claim rests on responsibility, not blame."},{"key":"c2","text":"return it now","logic_line":"Because the GEM ties London on care and wins on connection (S1), the law already bends when the moral case is accepted (S2), and an early, structured return protects the public and serves both sides (S3), the Stone should go now with a partnership.","supports":[{"key":"s1","text":"Cosmopolitanism, taken seriously, points to Cairo"},{"key":"s2","text":"The law is a choice, not a wall"},{"key":"s3","text":"Return well, and early"}],"counterclaim_response":"See response. / returning one object out of 100,000+ displaces no one. / our claim rests on responsibility, not blame."}]}'::jsonb, 'Tightened Claim 2 wording before partnership edit.', 'a3333333-3333-3333-3333-333333333302', '2026-11-17T16:00:00.000Z'),
  ('16c11a4a-0057-4623-af64-f02b262a9324', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 9), 7, '{"claims":[{"key":"c1","text":"The British Museum''s title is defective, and the duty to repair falls on the institution that still benefits.","logic_line":"Because the Stone changed hands as a spoil of war between empires (S1), keeping taken objects for being \"the better caretaker\" can''t be a universal rule (S2), and responsibility for an inherited wrong follows power and benefit (S3), the museum carries the duty to return it.","supports":[{"key":"s1","text":"A broken first link. A holding is just only if it was justly acquired and justly transferred."},{"key":"s2","text":"The caretaker maxim fails universalizability"},{"key":"s3","text":"Responsibility, not blame. Today''s trustees took nothing, but they hold the power and the benefit."}],"counterclaim_response":"See response. / returning one object out of 100,000+ displaces no one. / our claim rests on responsibility, not blame."},{"key":"c2","text":"return it with a partnership, now","logic_line":"Because the GEM ties London on care and wins on connection (S1), the law already bends when the moral case is accepted (S2), and an early, structured return protects the public and serves both sides (S3), the Stone should go now with a partnership.","supports":[{"key":"s1","text":"Cosmopolitanism, taken seriously, points to Cairo"},{"key":"s2","text":"The law is a choice, not a wall"},{"key":"s3","text":"Return well, and early"}],"counterclaim_response":"See response. / returning one object out of 100,000+ displaces no one. / our claim rests on responsibility, not blame."}]}'::jsonb, 'Claim 2 changed: return it now → return it with a partnership, now. Reason (Katie): Team 1''s Louvre point.', 'a3333333-3333-3333-3333-333333333303', '2026-11-18T17:30:00.000Z'),
  ('23a6aa54-ae72-4721-a87e-b7c5370cccba', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 10), 1, '{"claims":[{"key":"c1","text":"De-indexing records of acquittals and minor, old offenses is permissible, and often required.","logic_line":"Because an acquittal means the state failed to prove guilt (S1), permanent searchability punishes people beyond any sentence (S2), and de-indexing keeps the record while restoring \"practical obscurity\" (S3), the Delhi court''s approach is justified.","supports":[{"key":"s1","text":"Acquittal deserves respect. An acquitted person is legally innocent; a search result that suggests otherwise contradicts the court."},{"key":"s2","text":"Endless punishment is unjust"},{"key":"s3","text":"Obscurity, not erasure"}],"counterclaim_response":"(3) we never delete court records or journalism. / de-indexing changes findability, not truth. / an acquittal isn''t information about guilt; using it in hiring treats an innocent person as guilty."},{"key":"c2","text":"The right depends on the kind of information: consent and public power decide the tier.","logic_line":"Because information posted without consent was never fairly public (S1), people seeking public power invite scrutiny of their own words (S2), and government and press records serve accountability (S3), the right must be tiered.","supports":[{"key":"s1","text":"Consent: what was never fairly public should come down"},{"key":"s2","text":"Public power reduces protection"},{"key":"s3","text":"Records and journalism stay"}],"counterclaim_response":"(3) we never delete court records or journalism. / de-indexing changes findability, not truth. / an acquittal isn''t information about guilt; using it in hiring treats an innocent person as guilty."}]}'::jsonb, 'Imported from Team 3 case prep doc', 'a3333333-3333-3333-3333-333333333303', '2026-11-15T12:00:00.000Z'),
  ('12df2747-b65c-4eda-8962-cd0026b6277c', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 11), 3, '{"claims":[{"key":"c1","text":"Tainted money can be accepted when it wasn''t produced by the wrong, because refusing it costs lives and repairs nothing.","logic_line":"Because the HPV program saves lives that refusal would cost (S1), money''s moral status depends on how it was made more than who holds it (S2), and refusing doesn''t help the wronged (S3), partners may continue, with conditions.","supports":[{"key":"s1","text":"Lives are at stake"},{"key":"s2","text":"Distinguish the source of the money from the conduct of the donor"},{"key":"s3","text":"Refusal helps no victim"}],"counterclaim_response":"See response. / walking away from Gates personally is different from walking away from the patients. / the case doesn''t show other funders would replace the money, and girls who miss vaccination pay that cost. Distinguish: walking away from Gates personally is different from walking away from the patients."},{"key":"c2","text":"Nonprofits must refuse money that launders reputation or destroys the trust their mission depends on.","logic_line":"Because charity can be used to buy moral cover (S1), public health programs depend on community trust (S2), and accepting money is a public act that sends a message (S3), organizations must protect their independence and sometimes refuse.","supports":[{"key":"s1","text":"Reputation laundering is real. Giving can be used to change a public story about a donor."},{"key":"s2","text":"Health programs run on trust"},{"key":"s3","text":"Acceptance is expressive"}],"counterclaim_response":"See response. / walking away from Gates personally is different from walking away from the patients. / the case doesn''t show other funders would replace the money, and girls who miss vaccination pay that cost. Distinguish: walking away from Gates personally is different from walking away from the patients."}]}'::jsonb, 'Claim map at v3 from Team 3 prep.', 'a3333333-3333-3333-3333-333333333304', '2026-11-15T12:00:00.000Z'),
  ('177b5824-7822-4b48-b401-9233d822956c', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 12), 8, '{"claims":[{"key":"c1","text":"Some health speech may be regulated: checkable, false claims presented as expertise or used to sell, which risk serious physical harm.","logic_line":"Because the state may limit speech to prevent serious harm to others (S1), some health claims clearly cause such harm (S2), and borrowing medical authority creates duties ordinary conversation doesn''t have (S3), narrow regulation of those claims is justified.","supports":[{"key":"s1","text":"The harm principle, narrowly. Limit freedom only to prevent serious harm to others, and only by the least restrictive means that works."},{"key":"s2","text":"The harm is real and large"},{"key":"s3","text":"Borrowed authority carries duties. No one can check everything, so we must trust experts we can''t verify."}],"counterclaim_response":"(1) our tool is the least restrictive one *that works*, so demotion in feeds acts immediately, and repeated or commercial harmful claims can be removed. / we reject licensing everyone to stop the few. / comparisons mix many causes. Distinguish: we reject licensing everyone to stop the few."},{"key":"c2","text":"Credential labels and corrections are justified; licensing all health talk is not, and Article 4''s values test never is.","logic_line":"Because medical knowledge is fallible and often corrected by outsiders (S1), whoever decides what is false must not have a stake in the answer (S2), and labels inform without silencing (S3), the right tool is labels and corrections by an independent body.","supports":[{"key":"s1","text":"Fallibility. Silencing an opinion assumes we can''t be wrong."},{"key":"s2","text":"No stake in the answer"},{"key":"s3","text":"Labels pass; licensing fails"}],"counterclaim_response":"(1) our tool is the least restrictive one *that works*, so demotion in feeds acts immediately, and repeated or commercial harmful claims can be removed. / we reject licensing everyone to stop the few. / comparisons mix many causes. Distinguish: we reject licensing everyone to stop the few."}]}'::jsonb, 'Claim map at v8 from Team 3 prep.', 'a3333333-3333-3333-3333-333333333301', '2026-11-15T12:00:00.000Z'),
  ('f2f09ff4-035f-4b70-a614-433bb664e617', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 13), 6, '{"claims":[{"key":"c1","text":"Speakers of dehumanizing rhetoric share moral responsibility for violence it inspires.","logic_line":"Because you can be responsible for harm that passes through someone else''s free choice when you knowingly raise its risk (S1), a tiny chance times a huge audience is a serious risk (S2), and dehumanizing rhetoric is morally different from harsh opinion (S3), these speakers share responsibility.","supports":[{"key":"s1","text":"Responsibility isn''t a fixed pie. The attacker bears all of their own guilt; the speaker bears separate guilt for raising the risk, like a getaway driver."},{"key":"s2","text":"Moral mathematics. One in a million, times ten million listeners, is about ten people."},{"key":"s3","text":"Dehumanization is an act, not just an opinion"}],"counterclaim_response":"See response. / our claim is about raising risk, which is wrong even when no single attack can be traced, like drunk driving; where we assert a link, we use evidence such as a manifesto. / responsibility isn''t a fixed pie. Distinguish: our claim is about raising risk, which is wrong even when no single attack can be traced, like drunk driving; where we assert a link, we use evidence such as a manifesto."},{"key":"c2","text":"Responsibility scales with content, reach, foreseeability and persistence, but legal liability should stay at incitement to imminent violence.","logic_line":"Because speakers can prevent misuse and choose their words (S1), foreseeability grows once violence has followed (S2), and the power to punish \"dangerous rhetoric\" is itself dangerous (S3), moral responsibility scales while legal liability stays narrow.","supports":[{"key":"s1","text":"Speakers can prevent misuse"},{"key":"s2","text":"The second time is never random"},{"key":"s3","text":"The law must stay narrow"}],"counterclaim_response":"See response. / our claim is about raising risk, which is wrong even when no single attack can be traced, like drunk driving; where we assert a link, we use evidence such as a manifesto. / responsibility isn''t a fixed pie. Distinguish: our claim is about raising risk, which is wrong even when no single attack can be traced, like drunk driving; where we assert a link, we use evidence such as a manifesto."}]}'::jsonb, 'Claim map at v6 from Team 3 prep.', 'a3333333-3333-3333-3333-333333333302', '2026-11-15T12:00:00.000Z'),
  ('44d46026-401f-4046-a0a4-3b952620a3af', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 14), 2, '{"claims":[{"key":"c1","text":"AI companion companies bear moral responsibility for foreseeable harms their design makes more likely.","logic_line":"Because the technology is not neutral (S1), interactive companions differ from static media (S2), and the risk to vulnerable users was foreseeable (S3), companies share responsibility.","supports":[{"key":"s1","text":"The tech isn''t neutral. Training data, reinforcement from human feedback, and engagement-driven design shape what a bot says."},{"key":"s2","text":"Interactive, not static"},{"key":"s3","text":"Foreseeability"}],"counterclaim_response":"(3) parents matter, and we support tools for them. / (1) static media versus interactive, personalized relationship. / a 14-year-old in crisis is the paradigm case where choice isn''t fully free."},{"key":"c2","text":"The minimum duty is to recognize crisis signals, break character and connect users to human help; heavier limits should be proportionate.","logic_line":"Because the \"what\" of a product determines which guardrails it needs (S1), the safeguards are feasible and cheap compared with the harm (S2), and over-restriction has costs too (S3), the right duty is a firm minimum with proportionate additions.","supports":[{"key":"s1","text":"\"What\" sets the guardrails; \"how\" sets their strength"},{"key":"s2","text":"The minimum is feasible"},{"key":"s3","text":"Proportionality protects benefits too"}],"counterclaim_response":"(3) parents matter, and we support tools for them. / (1) static media versus interactive, personalized relationship. / a 14-year-old in crisis is the paradigm case where choice isn''t fully free."}]}'::jsonb, 'Claim map at v2 from Team 3 prep.', 'a3333333-3333-3333-3333-333333333303', '2026-11-15T12:00:00.000Z'),
  ('631cb6e1-147b-421e-b8b2-b2a5fe733172', '33333333-3333-3333-3333-333333333333', (select id from cases where number = 15), 3, '{"claims":[{"key":"c1","text":"Sentient animals have moral worth, so treating them as mere property is wrong.","logic_line":"Because the capacity to suffer is what makes suffering matter morally (S1), science and law increasingly recognize animal sentience (S2), and property law ignores that difference (S3), mere property status is wrong.","supports":[{"key":"s1","text":"Suffering matters wherever it occurs"},{"key":"s2","text":"Sentience is recognized"},{"key":"s3","text":"Property law treats a dog like a car"}],"counterclaim_response":"See response. / (2) legal personhood for corporations is a tool for holding rights and duties; animals can''t hold duties, so standing and guardianship fit better. / enforcement and standards matter more."},{"key":"c2","text":"Harm to animals is permissible only when necessary and minimized, which condemns factory farming but doesn''t require full personhood.","logic_line":"Because \"ought implies can\" and human needs are real (S1), legal standing can protect beings who can''t speak for themselves (S2), and factory farming fails the necessity test (S3), we support protection from unjustified harm, not full personhood.","supports":[{"key":"s1","text":"Transitional, realistic ethics"},{"key":"s2","text":"Standing without personhood"},{"key":"s3","text":"Factory farming fails the test"}],"counterclaim_response":"See response. / (2) legal personhood for corporations is a tool for holding rights and duties; animals can''t hold duties, so standing and guardianship fit better. / enforcement and standards matter more."}]}'::jsonb, 'Claim map at v3 from Team 3 prep.', 'a3333333-3333-3333-3333-333333333304', '2026-11-15T12:00:00.000Z')
insert into claim_map_confirmations (id, version_id, person_id, confirmed_at) values
  ('695123b8-57f7-493c-800c-87bbf09fe972', '34061253-06bc-454e-9a8d-cff00b2d4bcb', 'a3333333-3333-3333-3333-333333333301', '2026-11-16T12:00:00.000Z'),
